list_shipping_profiles.code:
import (
	"fmt"
)

resp, err := client.ShippingProfiles().ListShippingProfiles(ctx, map[string]any{
	"search": "metro",
	"sort":   "name",
	"order":  "asc",
	"limit":  20,
}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["shipping_profiles"].([]any) {
	profile := row.(map[string]any)
	fmt.Println(profile["id"], profile["name"], profile["rule_preference"], profile["default"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

